package com.wanfo.bi.domain.chart;
import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
import static org.junit.jupiter.api.Assertions.assertThrows;
import org.junit.jupiter.api.Test;
import com.wanfo.bi.domain.query.QueryModel;
class ChartTypesTest {
    QueryModel pieQuery(){var q=new QueryModel();q.addDimension("city","c");q.addMetric("id","SUM","v");return q;}
    @Test void allowsExtendedTypes(){assertDoesNotThrow(()->ChartTypes.validateShape("area",pieQuery()));assertDoesNotThrow(()->ChartTypes.validateShape("ring",pieQuery()));}
    @Test void gaugeRequiresSingleMetricNoDim(){var q=new QueryModel();q.addMetric("id","SUM","v");assertDoesNotThrow(()->ChartTypes.validateShape("gauge",q));q.addDimension("city","c");assertThrows(IllegalArgumentException.class,()->ChartTypes.validateShape("gauge",q));}
    @Test void scatterRequiresTwoMetrics(){var q=pieQuery();assertThrows(IllegalArgumentException.class,()->ChartTypes.validateShape("scatter",q));q.addMetric("amount","SUM","a");assertDoesNotThrow(()->ChartTypes.validateShape("scatter",q));}
    @Test void comboNeedsTwoMetrics(){var q=pieQuery();assertThrows(IllegalArgumentException.class,()->ChartTypes.validateShape("combo",q));q.addMetric("amount","SUM","a");assertDoesNotThrow(()->ChartTypes.validateShape("combo",q));}
    @Test void mapRequiresRegionDimAndMetric(){var q=pieQuery();assertDoesNotThrow(()->ChartTypes.validateShape("map",q));q.addMetric("x","SUM","x2");assertThrows(IllegalArgumentException.class,()->ChartTypes.validateShape("map",q));}
    @Test void seriesOnlyOnCartesianWithDistinctDimensionAndAggregates(){var q=pieQuery();q.addDimension("channel","s");for(var type:java.util.List.of("line","bar","stack","percent","area","hbar"))assertDoesNotThrow(()->ChartTypes.validateShape(type,q));assertThrows(IllegalArgumentException.class,()->ChartTypes.validateShape("radar",q));q.getDimensions().get(1).setField("city");assertThrows(IllegalArgumentException.class,()->ChartTypes.validateShape("line",q));q.getDimensions().get(1).setField("channel");q.getMetrics().get(0).setAgg("NONE");assertThrows(IllegalArgumentException.class,()->ChartTypes.validateShape("bar",q));}
    @Test void newAnalyticalTypesValidateTheirRequiredRoles(){var grouped=new QueryModel();grouped.addDimension("x","x");grouped.addDimension("y","y");grouped.addMetric("value","SUM","v");for(var type:java.util.List.of("heatmap","sunburst","sankey"))assertDoesNotThrow(()->ChartTypes.validateShape(type,grouped));assertThrows(IllegalArgumentException.class,()->ChartTypes.validateShape("treemap",grouped));var rawGroup=new QueryModel();rawGroup.addDimension("category","c");rawGroup.addMetric("value","NONE","v");assertDoesNotThrow(()->ChartTypes.validateShape("boxplot",rawGroup));var histogram=new QueryModel();histogram.addMetric("value","NONE","v");assertDoesNotThrow(()->ChartTypes.validateShape("histogram",histogram));var geo=new QueryModel();geo.addMetric("lon","NONE","lon");geo.addMetric("lat","NONE","lat");assertDoesNotThrow(()->ChartTypes.validateShape("geo-map",geo));}
}
